function priorityMatrix(opts){
  opts=opts||{};
  function items(s){ return String(s||'').split(/[\n,，;；]+/).map(function(x){return x.trim();}).filter(Boolean); }
  var groups=[['① 重要且紧急 · 立刻做', items(opts.q1)],
              ['② 重要不紧急 · 计划做', items(opts.q2)],
              ['③ 紧急不重要 · 速办或委托', items(opts.q3)],
              ['④ 不紧急不重要 · 少做或删除', items(opts.q4)]];
  var L=['# 优先级矩阵（艾森豪威尔）',''];
  for(var g=0;g<groups.length;g++){
    L.push('## '+groups[g][0]);
    var arr=groups[g][1];
    if(arr.length){ for(var i=0;i<arr.length;i++) L.push('- [ ] '+arr[i]); }
    else { L.push('- [ ] ____'); }
    L.push('');
  }
  L.push('> 目标：把时间尽量推向 ②，减少 ③ 与 ④。');
  return L.join('\n').replace(/\n+$/,'');
}

var EXPORTS={priorityMatrix:priorityMatrix};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PriorityForgePure = EXPORTS; }
